import pandas as pd, numpy as np
from lmfit.models import LorentzianModel, LinearModel, QuadraticModel, GaussianModel
def load(f):
    d=pd.read_csv(f); return d.shift_cm1.values, d.intensity.values
def fit_lor(x,y,lo,hi,x0,bgdeg=1,sig_fix=None):
    m=(x>lo)&(x<hi); xs,ys=x[m],y[m]
    bg = LinearModel(prefix='b_') if bgdeg==1 else QuadraticModel(prefix='b_')
    mod=LorentzianModel(prefix='p_')+bg
    p=mod.make_params(p_center=x0,p_amplitude=(ys.max()-np.median(ys))*np.pi*5,p_sigma=5)
    p['p_center'].set(min=x0-8,max=x0+8); p['p_sigma'].set(min=0.5,max=30)
    if bgdeg==1:
        p['b_slope'].set(value=0); p['b_intercept'].set(value=np.median(ys))
    else:
        p['b_a'].set(value=0); p['b_b'].set(value=0); p['b_c'].set(value=np.median(ys))
    if sig_fix: p['p_sigma'].set(value=sig_fix,vary=False)
    r=mod.fit(ys,p,x=xs)
    h=r.params['p_amplitude'].value/(np.pi*r.params['p_sigma'].value)
    # null model: background only
    null=(bg).fit(ys,(bg).make_params(**({'slope':0,'intercept':np.median(ys)} if bgdeg==1 else {'a':0,'b':0,'c':np.median(ys)})),x=xs)
    n=len(ys); rss1=np.sum(r.residual**2); rss0=np.sum(null.residual**2)
    F=((rss0-rss1)/3)/(rss1/(n-5))
    return dict(c=r.params['p_center'].value, ce=r.params['p_center'].stderr, fwhm=2*r.params['p_sigma'].value, h=h, area=r.params['p_amplitude'].value, F=F, dBIC=n*np.log(rss1/n)+5*np.log(n)-(n*np.log(rss0/n)+2*np.log(n)), sd=np.std(r.residual))
x1,y1=load('spectrum_flake1.csv'); x2,y2=load('spectrum_flake2.csv')
print('Sensitivity of E2g fit (Lorentzian + bg)')
for lbl,(x,y) in [('flake1',(x1,y1)),('flake2',(x2,y2))]:
    for lo,hi in [(1300,1440),(1320,1420),(1280,1460)]:
        for deg in [1,2]:
            try:
                o=fit_lor(x,y,lo,hi,1367,deg)
                print(f'{lbl} win {lo}-{hi} bg{deg}: center {o[\"c\"]:.2f}+-{o[\"ce\"] or 0:.2f}  FWHM {o[\"fwhm\"]:.1f}  height {o[\"h\"]:.0f}  area {o[\"area\"]:.0f}  F {o[\"F\"]:.1f}  dBIC(lor-null) {o[\"dBIC\"]:.1f}  resid_sd {o[\"sd\"]:.1f}')
            except Exception as e: print(lbl,lo,hi,deg,'fail',e)
# Si 520 fit
print()
for lbl,(x,y) in [('flake1',(x1,y1)),('flake2',(x2,y2))]:
    o=fit_lor(x,y,505,535,520.5,1)
    print(lbl,'Si line Lorentz center %.2f+-%.2f FWHM %.2f height %.0f area %.0f'%(o['c'],o['ce'] or 0,o['fwhm'],o['h'],o['area']))
" 2>&1

